    // Professional Rent Management Page Keys
    'rentManagement.badge': 'Core Operational Service: Tenant & Rent Management',
    'rentManagement.headline': 'Professional Tenant & Rent Management',
    'rentManagement.highlightBox': 'Manage rental schedules, payment records, tenant communication, and owner financial reporting through one organized workspace.',
    'rentManagement.subtext': 'A transparent, accountable management system for property owners: structured rent schedules, verified payment confirmations, auditable double-entry accounting records, and clear net owner statements.',
    'rentManagement.cta.openOwnerWorkspace': 'Open Owner Workspace',
    'rentManagement.cta.registerProperty': 'Register a Property',
    'rentManagement.cta.companyPortal': 'Management Companies Portal',
    
    // Four-Stage Operational Flow
    'rentManagement.flow.badge': 'Four-Stage Operational Flow',
    'rentManagement.flow.heading': 'How HomeHub Supports Rental Management',
    'rentManagement.flow.subtext': 'Each stage operates with explicit verification, authenticated workflows, and auditable accounting records.',
    
    'rentManagement.step1.title': '1. Monthly Rent Schedules & Due Notices',
    'rentManagement.step1.desc': 'Rental schedules are generated directly from active lease terms. Digital rent notices and statements inform tenants of upcoming due dates without manual intervention.',
    
    'rentManagement.step2.title': '2. Authorized Management & Tenant Communication',
    'rentManagement.step2.desc': 'Under approved management agreements, routine inquiries, payment logging (digital or cash recording), and maintenance intake are handled efficiently while keeping owners informed.',
    
    'rentManagement.step3.title': '3. Payment Confirmation & Accounting Records',
    'rentManagement.step3.desc': 'Received payments are verified before entry. Confirmed transactions are recorded directly in PostgreSQL double-entry ledgers (journal entries and ledger lines) for verifiable auditing.',
    
    'rentManagement.step4.title': '4. Owner Financial Reporting & Settlement Status',
    'rentManagement.step4.desc': 'Dynamic fees apply only to confirmed collected rent according to your operating model. Itemized net owner balances and settlement statements are readily accessible in your workspace.',
    
    // Operating Models Matrix
    'rentManagement.models.badge': 'Operating Models & Fee Allocation',
    'rentManagement.models.heading': 'Three Flexible Operating Models',
    'rentManagement.models.subtext': 'Fees are governed strictly by the agreed operating model. Unset by default, fees apply exclusively to confirmed collected rent with 0% tenant surcharge.',
    
    'rentManagement.model.fullyManaged.title': 'Fully Managed',
    'rentManagement.model.fullyManaged.badge': 'Platform + Rent + Mgmt Fee',
    'rentManagement.model.fullyManaged.desc': 'HomeHub or assigned licensed manager manages the complete leasing, collection, and property lifecycle. Platform Fee, Rent Fee, and Management Fee apply to confirmed collected rent.',
    
    'rentManagement.model.agentListed.title': 'Agent-Listed Platform-Managed',
    'rentManagement.model.agentListed.badge': 'Platform + Mgmt Fee',
    'rentManagement.model.agentListed.desc': 'A commercial agent leases the property; HomeHub handles ongoing property management and accounting. Platform Fee and Management Fee apply; Rent Fee is not applicable.',
    
    'rentManagement.model.agentOperated.title': 'Agent-Operated',
    'rentManagement.model.agentOperated.badge': 'Platform Fee Only',
    'rentManagement.model.agentOperated.desc': 'The agent or owner directly operates property management. Only the standard Platform Fee applies; Rent Fee and Management Fee are not applicable.',
    
    // Financial Governance & Architectural Guarantees
    'rentManagement.gov.badge': 'Financial Governance & Protections',
    'rentManagement.gov.heading': 'Core Financial Architectural Guarantees',
    'rentManagement.gov.subtext': 'Security invariants, authoritative ownership validation, and dynamic fee enforcement built into platform architecture.',
    
    'rentManagement.gov.item1.title': 'Configurable Dynamic 3-Fee Model',
    'rentManagement.gov.item1.desc': 'HomeHub operates under a dynamic 3-fee policy (Platform Fee, Rent Fee, Management Fee) fetched dynamically from financial_policies. Fees apply exclusively to CONFIRMED rent collections with strictly 0% tenant surcharge. Security deposits incur 0% commission.',
    
    'rentManagement.gov.item2.title': 'Strict Ownership vs. Management Separation',
    'rentManagement.gov.item2.desc': 'Property ownership is strictly defined by ownership_records. Management agreements authorize property operations and tenant handling without transferring ownership or deed rights.',
    
    'rentManagement.gov.item3.title': 'Auditable Double-Entry Ledger Security',
    'rentManagement.gov.item3.desc': 'All balance adjustments, rent disbursements, and fee deductions are governed by authoritative double-entry ledgers in PostgreSQL (journal_entries and ledger_lines), eliminating shadow balances and unverified transactions.',

    // Final CTA Section
    'rentManagement.final.heading': 'Ready to Organize Your Property & Rent Management?',
